269	// ---- 四种授权状态都入列；标识、归属、接收方、有效期、撤回时间与范围形态原样保留 ----
270	
271	func TestListAuthorizationsIncludesEveryLifecycleStateWithSavedValues(t *testing.T) {
272		f := setupListAuthFixture(t)
273		now := f.clk.t
274	
275		rows, err := f.s.ListAuthorizations(doc, f.pidA, rcv.ID)
276		if err != nil {
277			t.Fatalf("list: %v", err)
278		}
279		// 生效中、未开始、已到期、已撤回各保留一条；撤回时间有值也不能隐藏该条。
280		assertAuthIDSet(t, rows, f.active.ID, f.future.ID, f.expired.ID, f.revoked.ID)
281	
282		// 列表用于查看历史，不是接收方当前可用授权合集：逐行核对状态归类。
283		active := findListedAuth(t, rows, f.active.ID)
284		if !active.ActiveAt(now) || active.RevokedAt != nil {
285			t.Fatalf("active grant misclassified: %+v", active)
286		}
287		future := findListedAuth(t, rows, f.future.ID)
288		if future.ActiveAt(now) || future.RevokedAt != nil || !now.Before(future.StartsAt) {
289			t.Fatalf("not-started grant misclassified: %+v", future)
290		}
291		expired := findListedAuth(t, rows, f.expired.ID)
292		if expired.ActiveAt(now) || expired.RevokedAt != nil || !expired.ExpiresAt.Before(now) {
293			t.Fatalf("expired grant misclassified: %+v", expired)
294		}
295		revoked := findListedAuth(t, rows, f.revoked.ID)
296		if revoked.RevokedAt == nil || revoked.ActiveAt(now) {
297			t.Fatalf("revoked grant misclassified: %+v", revoked)
298		}
299	
300		// 整类范围、限定记录范围、两者并存的混合授权各自保留原本的就诊、类别
301		// 与记录选择：不合并成一条，也不把混合范围改成整类范围。
302		if len(active.Scopes) != 1 || active.Scopes[0] != (Scope{EncounterID: f.eA1, Category: Diagnosis}) ||
303			len(active.Selections) != 0 {
304			t.Fatalf("whole-category scope altered: %+v", active)
305		}
306		if len(future.Scopes) != 0 || len(future.Selections) != 1 ||
307			future.Selections[0] != sel(f.eA1, Diagnosis, f.recA1) {
308			t.Fatalf("limited scope altered: %+v", future.Selections)
309		}
310		if len(expired.Scopes) != 1 || expired.Scopes[0] != (Scope{EncounterID: f.eA2, Category: Diagnosis}) ||
311			len(expired.Selections) != 0 {
312			t.Fatalf("expired whole-category scope altered: %+v", expired)
313		}
314		if len(revoked.Scopes) != 1 || revoked.Scopes[0] != (Scope{EncounterID: f.eA1, Category: Order}) ||
315			len(revoked.Selections) != 1 || revoked.Selections[0] != sel(f.eA1, Diagnosis, f.recA2) {
316			t.Fatalf("mixed scope altered on listing: scopes=%+v selections=%+v",
317				revoked.Scopes, revoked.Selections)
318		}
319	
320		// 结果与正式保存的授权逐字段一致：标识、归属、接收方、有效期、撤回时间、
321		// 范围、创建时间全部保持已保存的值。
322		for _, id := range []ID{f.active.ID, f.future.ID, f.expired.ID, f.revoked.ID} {
323			stored, err := f.s.GetAuthorization(doc, f.pidA, id)
324			if err != nil {
325				t.Fatalf("get stored %q: %v", id, err)
326			}
327			listed := findListedAuth(t, rows, id)
328			if !reflect.DeepEqual(listed, stored) {
329				t.Fatalf("listed authorization %q diverges from stored:\nlisted=%+v\nstored=%+v",
330					id, listed, stored)
331			}
332		}
333	
334		// 接收方读取临床内容的规则保持原样：只有生效中的整类授权当前可用；
335		// 未开始、已到期、已撤回的历史授权不提供任何读取覆盖。
336		res, err := f.s.Read(rcv, f.pidA, f.eA1, Diagnosis)
337		if err != nil {
338			t.Fatalf("active grant should still allow read: %v", err)
339		}
340		ids := readRecordIDs(res)
341		if len(res.Records) != 2 || !ids[f.recA1] || !ids[f.recA2] {
342			t.Fatalf("active whole-category read = %+v, want both effective diagnoses", res.Records)
343		}
344		if _, err := f.s.Read(rcv, f.pidA, f.eA1, Order); !errors.Is(err, ErrAccessDenied) {
345			t.Fatalf("revoked mixed grant must not cover orders: %v", err)
346		}
347		if _, err := f.s.Read(rcv, f.pidA, f.eA2, Diagnosis); !errors.Is(err, ErrAccessDenied) {
348			t.Fatalf("expired grant must not cover reading: %v", err)
349		}
350	}
351	
352	// ---- 患者档案停用后内部使用者仍可查看此前建立的授权 ----
353	
354	func TestListAuthorizationsRemainsAvailableAfterDeactivation(t *testing.T) {
355		f := setupListAuthFixture(t)
356	
357		if err := f.s.DeactivatePatient(doc, f.pidA); err != nil {
358			t.Fatalf("deactivate: %v", err)
359		}
360		auditAfterDeactivate := len(mustAudit(t, f.s, f.pidA))
361		auditBBefore := len(mustAudit(t, f.s, f.pidB))
362		totalBefore := totalAuthorizations(f.s)
363	
364		// 停用不清空、不拒绝：全部五条历史授权仍在，顺序仍按标识升序。
365		allA, err := f.s.ListAuthorizations(doc, f.pidA, "")
366		if err != nil {
367			t.Fatalf("list after deactivation: %v", err)
368		}
369		assertAuthIDSet(t, allA, f.active.ID, f.future.ID, f.expired.ID, f.revoked.ID, f.otherRcv.ID)
370		assertAuthIDsSorted(t, allA)
371	
372		// 接收方过滤同样可用；已撤回授权带撤回时间出现。
373		aRcv, err := f.s.ListAuthorizations(doc, f.pidA, rcv.ID)
374		if err != nil {
375			t.Fatalf("filtered list after deactivation: %v", err)
376		}
377		assertAuthIDSet(t, aRcv, f.active.ID, f.future.ID, f.expired.ID, f.revoked.ID)
378		revoked := findListedAuth(t, aRcv, f.revoked.ID)
379		stored, err := f.s.GetAuthorization(doc, f.pidA, f.revoked.ID)
380		if err != nil {
381			t.Fatalf("get revoked: %v", err)
382		}
383		if revoked.RevokedAt == nil || !revoked.RevokedAt.Equal(*stored.RevokedAt) {
384			t.Fatalf("revoked-at not preserved: listed=%v stored=%v",
385				revoked.RevokedAt, stored.RevokedAt)
386		}
387		if !reflect.DeepEqual(revoked, stored) {
388			t.Fatalf("revoked authorization diverges from stored after deactivation")
389		}
390	
391		// 另一名患者不受牵连。
392		bAll, err := f.s.ListAuthorizations(doc, f.pidB, "")
393		if err != nil {
394			t.Fatalf("list patient B after A deactivated: %v", err)
395		}
396		assertAuthIDSet(t, bAll, f.grantB.ID)
397	
398		// 停用只影响接收方读取等既有规则，不改变内部历史视图的只读性质。
399		if _, err := f.s.Read(rcv, f.pidA, f.eA1, Diagnosis); !errors.Is(err, ErrAccessDenied) {
400			t.Fatalf("receiver read after deactivation err = %v, want ErrAccessDenied", err)
401		}
402	
403		// 查看列表本身不新增授权或审计。
404		if got := len(mustAudit(t, f.s, f.pidA)); got != auditAfterDeactivate {
405			t.Fatalf("listing added audit events: %d -> %d", auditAfterDeactivate, got)
406		}
407		if got := len(mustAudit(t, f.s, f.pidB)); got != auditBBefore {
408			t.Fatalf("listing patient B changed its audit: before=%d after=%d",
409				auditBBefore, got)
410		}
411		if totalAuthorizations(f.s) != totalBefore {
412			t.Fatalf("listing changed authorization count: before=%d after=%d",
413				totalBefore, totalAuthorizations(f.s))
414		}
415	}
416	
417	// ---- 接收方身份不能使用内部查询；查看列表不新增授权或审计 ----
418	
419	func TestListAuthorizationsDeniedToReceiversAndCreatesNothing(t *testing.T) {
420		f := setupListAuthFixture(t)
421	
422		auditABefore := len(mustAudit(t, f.s, f.pidA))
423		auditBBefore := len(mustAudit(t, f.s, f.pidB))
424		authBefore := totalAuthorizations(f.s)
425	
426		// 即使 rcv 对患者甲持有生效中的授权，也不能使用内部查询：
427		// ErrAccessDenied，且不带回任何授权资料（即使按自身接收方过滤也不行）。
428		if got, err := f.s.ListAuthorizations(rcv, f.pidA, ""); !errors.Is(err, ErrAccessDenied) || len(got) != 0 {
429			t.Fatalf("holder receiver list = %d rows, err %v; want 0 rows, ErrAccessDenied", len(got), err)
430		}
431		if got, err := f.s.ListAuthorizations(rcv, f.pidA, rcv.ID); !errors.Is(err, ErrAccessDenied) || len(got) != 0 {
432			t.Fatalf("holder receiver self-filter = %d rows, err %v; want 0 rows, ErrAccessDenied", len(got), err)
433		}
434		// 无授权的接收方、无效身份同样被拒绝，且不暴露患者是否存在。
435		if _, err := f.s.ListAuthorizations(ReceiverActor("rcv-c"), f.pidA, ""); !errors.Is(err, ErrAccessDenied) {
436			t.Fatalf("stranger receiver err = %v, want ErrAccessDenied", err)
437		}
438		if _, err := f.s.ListAuthorizations(Actor{ID: "", Kind: "internal"}, f.pidA, ""); !errors.Is(err, ErrAccessDenied) {
439			t.Fatalf("blank actor id err = %v, want ErrAccessDenied", err)
440		}
441		if _, err := f.s.ListAuthorizations(Actor{ID: "x", Kind: "other"}, f.pidA, ""); !errors.Is(err, ErrAccessDenied) {
442			t.Fatalf("unknown actor kind err = %v, want ErrAccessDenied", err)
443		}
444	
445		// 一批合法查看（含成功空列表与不存在患者的失败）同样不留痕迹。
446		if _, err := f.s.ListAuthorizations(doc, f.pidA, ""); err != nil {
447			t.Fatalf("list A: %v", err)
448		}
449		if _, err := f.s.ListAuthorizations(doc, f.pidA, rcv.ID); err != nil {
450			t.Fatalf("list A/rcv: %v", err)
451		}
452		if _, err := f.s.ListAuthorizations(doc, f.pidC, ""); err != nil {
453			t.Fatalf("list C: %v", err)
454		}
455		if _, err := f.s.ListAuthorizations(doc, "pat_missing", ""); !errors.Is(err, ErrNotFound) {
456			t.Fatal("missing patient must stay ErrNotFound")
457		}
458	
459		if got := len(mustAudit(t, f.s, f.pidA)); got != auditABefore {
460			t.Fatalf("listing added audit for A: %d -> %d", auditABefore, got)
461		}
462		if got := len(mustAudit(t, f.s, f.pidB)); got != auditBBefore {
463			t.Fatalf("listing added audit for B: %d -> %d", auditBBefore, got)
464		}
465		if got := totalAuthorizations(f.s); got != authBefore {
466			t.Fatalf("listing changed authorization count: %d -> %d", authBefore, got)
467		}
468	}
