	// 核对：条数、患者归属、撤回授权在“全部”与“insurer-1”两张清单中都出现。
	belongsToPatient := func(rows []clinical.Authorization) bool {
		for _, a := range rows {
			if a.PatientID != patient.ID {
				return false
			}
		}
		return true
	}
	listHas := func(rows []clinical.Authorization, id clinical.ID) bool {
		for _, a := range rows {
			if a.ID == id {
				return true
			}
		}
