	if !errors.Is(deniedErr, clinical.ErrAccessDenied) || len(deniedRows) != 0 ||
		!errors.Is(deniedSelfErr, clinical.ErrAccessDenied) || len(deniedSelfRows) != 0 {
		die("接收方调用内部查询应返回 0 条与 ErrAccessDenied，实际得到 %d 条/%v 与 %d 条/%v",
